files.examples/01_isolation.sql:
-- LEARN(sql.security-ops.rls): the tenant boundary is enforced by the table, not by each query.
CREATE TABLE projects (
  id        int PRIMARY KEY,
  tenant_id bigint NOT NULL,
  name      text NOT NULL
);
INSERT INTO projects VALUES
  (1, 1, 'Acme brake controller'),
  (2, 1, 'Acme pump firmware'),
  (3, 2, 'Globex rail signalling');

-- The app sets app.tenant per transaction. Unset or empty gives NULL,
-- and NULL = anything is never true: no tenant, no rows.
ALTER TABLE projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON projects
  USING (tenant_id = nullif(current_setting('app.tenant', true), '')::bigint);

-- This session owns the table, and owners skip policies...
SELECT count(*) AS seen_by_owner FROM projects;
-- ...unless the table forces them on its owner as well.
ALTER TABLE projects FORCE ROW LEVEL SECURITY;
SELECT count(*) AS no_tenant_set FROM projects;

SELECT set_config('app.tenant', '1', true);
SELECT id, name FROM projects ORDER BY id;
-- The policy is a predicate the planner adds to every query on the table.
EXPLAIN (COSTS OFF) SELECT id, name FROM projects;

-- Rows you cannot see cannot be changed: no error, just nothing matched.
UPDATE projects SET name = 'renamed by Acme' WHERE id = 3;
DELETE FROM projects WHERE id = 3;

SELECT set_config('app.tenant', '2', true);
SELECT id, name FROM projects ORDER BY id;

-- A new row must pass the policy too: USING doubles as WITH CHECK.
INSERT INTO projects VALUES (4, 1, 'planted by Globex');

files.examples/02_constraints.sql:
CREATE TABLE projects (
  id        int PRIMARY KEY,
  tenant_id bigint NOT NULL,
  code      text NOT NULL UNIQUE,
  name      text NOT NULL
);
CREATE TABLE requirements (
  id         int PRIMARY KEY,
  tenant_id  bigint NOT NULL,
  project_id int NOT NULL REFERENCES projects,
  title      text NOT NULL
);
INSERT INTO projects VALUES (1, 1, 'BRK', 'Acme brakes'), (3, 2, 'RAIL', 'Globex rail');

ALTER TABLE projects ENABLE ROW LEVEL SECURITY;
ALTER TABLE projects FORCE ROW LEVEL SECURITY;
ALTER TABLE requirements ENABLE ROW LEVEL SECURITY;
ALTER TABLE requirements FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON projects
  USING (tenant_id = nullif(current_setting('app.tenant', true), '')::bigint);
CREATE POLICY tenant_isolation ON requirements
  USING (tenant_id = nullif(current_setting('app.tenant', true), '')::bigint);

SELECT set_config('app.tenant', '1', true);
SELECT code FROM projects;

-- The unique index sees every tenant's rows: "nothing inserted" means
-- some other tenant already uses the code RAIL.
INSERT INTO projects VALUES (10, 1, 'RAIL', 'Acme rail test rig')
  ON CONFLICT (code) DO NOTHING;
-- The foreign key check sees them too: Acme can attach to a Globex project.
INSERT INTO requirements VALUES (100, 1, 3, 'Stops within 300 m');
SELECT r.title, p.name AS project FROM requirements r LEFT JOIN projects p ON p.id = r.project_id;

-- Fix: make the tenant part of every key, so constraints stay inside one tenant.
DELETE FROM requirements;
ALTER TABLE requirements DROP CONSTRAINT requirements_project_id_fkey;
ALTER TABLE projects DROP CONSTRAINT projects_code_key,
  ADD UNIQUE (tenant_id, code),
  ADD UNIQUE (tenant_id, id);
ALTER TABLE requirements
  ADD FOREIGN KEY (tenant_id, project_id) REFERENCES projects (tenant_id, id);

INSERT INTO projects VALUES (10, 1, 'RAIL', 'Acme rail test rig');
INSERT INTO requirements VALUES (101, 1, 3, 'Stops within 300 m');

files.examples/03_pooled_context.sql:
-- Runtime sql-nontx: one connection, several transactions, the way a pool
-- hands the same server session to request after request.
CREATE TABLE projects (id int PRIMARY KEY, tenant_id bigint NOT NULL, name text NOT NULL);
INSERT INTO projects VALUES (1, 1, 'Acme brakes'), (2, 2, 'Globex rail');
ALTER TABLE projects ENABLE ROW LEVEL SECURITY;
ALTER TABLE projects FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON projects
  USING (tenant_id = nullif(current_setting('app.tenant', true), '')::bigint);

-- Request 1 (tenant 1): the setting lives exactly as long as its transaction.
BEGIN;
SELECT set_config('app.tenant', '1', true);
SELECT name FROM projects;
COMMIT;

-- Request 2 forgot to set a tenant: the variable is still defined, but empty.
SELECT quote_literal(current_setting('app.tenant', true)) AS leftover,
       count(*) AS visible
FROM projects;

-- Request 3 (tenant 2) sets it for the whole session instead...
SELECT set_config('app.tenant', '2', false);
SELECT name FROM projects;
-- ...and request 4, someone else's, runs on the same connection without
-- setting a tenant. It inherits tenant 2.
SELECT name FROM projects;

-- The same policy without nullif: an empty leftover breaks the cast.
ALTER POLICY tenant_isolation ON projects
  USING (tenant_id = current_setting('app.tenant', true)::bigint);
RESET app.tenant;
SELECT name FROM projects;
